72:   public on(event: string, handler: HookHandler<any, any>): () => void {
73:     if (!this.hookHandlers.has(event)) {
74:       this.hookHandlers.set(event, []);
75:     }
76:     this.hookHandlers.get(event)!.push(handler);
77:     return () => {
78:       const list = this.hookHandlers.get(event);
79:       if (list) {
80:         const idx = list.indexOf(handler);
81:         if (idx !== -1) list.splice(idx, 1);
82:       }
83:     };
84:   }
